static int K;

static int by_window(const void* x, const void* y) {
    return strncmp(*(char* const*) x, *(char* const*) y, K);
}

int distinctWindows(char* s, int k) {
    int count = strlen(s) - k + 1, distinct = 1;
    char** starts = malloc(count * sizeof(char*));
    for (int i = 0; i < count; i++) starts[i] = s + i;
    K = k;
    qsort(starts, count, sizeof(char*), by_window);
    for (int i = 1; i < count; i++) if (strncmp(starts[i - 1], starts[i], k) != 0) distinct++;
    free(starts);
    return distinct;
}

