    def distinctWindows(self, s: str, k: int) -> int:
        M1, M2, B = 1_000_000_007, 1_000_000_009, 131
        top1, top2 = pow(B, k - 1, M1), pow(B, k - 1, M2)
        h1 = h2 = 0
        for c in s[:k]:
            h1, h2 = (h1 * B + ord(c)) % M1, (h2 * B + ord(c)) % M2
        seen = {(h1, h2)}
        for i in range(k, len(s)):
            out, c = ord(s[i - k]), ord(s[i])
            h1 = ((h1 - out * top1) * B + c) % M1
            h2 = ((h2 - out * top2) * B + c) % M2
            seen.add((h1, h2))
        return len(seen)

