class Solution {
    public int distinctWindows(String s, int k) {
        final long M1 = 1_000_000_007L, M2 = 1_000_000_009L, B = 131;
        long top1 = 1, top2 = 1;
        for (int i = 1; i < k; i++) { top1 = top1 * B % M1; top2 = top2 * B % M2; }
        long h1 = 0, h2 = 0;
        for (int i = 0; i < k; i++) { h1 = (h1 * B + s.charAt(i)) % M1; h2 = (h2 * B + s.charAt(i)) % M2; }
        Set<Long> seen = new HashSet<>();
        seen.add(h1 << 32 | h2);
        for (int i = k; i < s.length(); i++) {
            long out = s.charAt(i - k), c = s.charAt(i);
            h1 = ((h1 - out * top1 % M1 + M1) * B + c) % M1;
            h2 = ((h2 - out * top2 % M2 + M2) * B + c) % M2;
            seen.add(h1 << 32 | h2);
        }
        return seen.size();
    }
}

