static int by_key(const void* x, const void* y) {
    unsigned long long a = *(const unsigned long long*) x, b = *(const unsigned long long*) y;
    return a < b ? -1 : a > b;
}

int distinctWindows(char* s, int k) {
    const long long M1 = 1000000007LL, M2 = 1000000009LL, B = 131;
    int n = strlen(s), count = n - k + 1, distinct = 1;
    long long top1 = 1, top2 = 1;
    for (int i = 1; i < k; i++) { top1 = top1 * B % M1; top2 = top2 * B % M2; }
    long long h1 = 0, h2 = 0;
    for (int i = 0; i < k; i++) { h1 = (h1 * B + s[i]) % M1; h2 = (h2 * B + s[i]) % M2; }
    unsigned long long* keys = malloc(count * sizeof(unsigned long long));
    keys[0] = (unsigned long long) h1 << 32 | h2;
    for (int i = k; i < n; i++) {
        long long out = s[i - k], c = s[i];
        h1 = ((h1 - out * top1 % M1 + M1) * B + c) % M1;
        h2 = ((h2 - out * top2 % M2 + M2) * B + c) % M2;
        keys[i - k + 1] = (unsigned long long) h1 << 32 | h2;
    }
    qsort(keys, count, sizeof(unsigned long long), by_key);
    for (int i = 1; i < count; i++) if (keys[i] != keys[i - 1]) distinct++;
    free(keys);
    return distinct;
}
